import { Controller, HttpCode, Post, Req } from '@nestjs/common';
import type { Request } from 'express';
import * as checks from '../common/checks';
import { transaction } from '../common/db';
import { ApiError } from '../common/errors';
import { currentUser } from '../common/user';

// 가정: 이메일 공유는 외부 메일 발송 모듈이 없어 수신자 이메일 주소가 있으면 발송 요청됨으로 처리한다.
// 가정: 공유 권한은 문서 작성자 또는 수정 권한을 받은 사용자에게 있다.
// 가정: 공유 대상은 재직자 상태의 직원(그룹웨어 사용자)으로 한정한다.
const SHARE_METHODS = ['NOTE', 'EMAIL'];
const ACTIVE_STATUS = '재직자';

@Controller('api/v1')
export class FnSfr04105Controller {
  @Post('/office-documents/:officeDocumentId/share')
  @HttpCode(200)
  async shareOfficeDocument(@Req() req: Request) {
    const user = currentUser(req);
    user.require('임직원');
    const data = checks.inputOf(req.body);
    const documentId = req.params['officeDocumentId'];
    if (!/^\d+$/.test(String(documentId))) {
      throw new ApiError(400, 'VALIDATION_FAILED', '문서 ID가 올바르지 않습니다.');
    }
    const shareMethod = data['shareMethod'];
    if (typeof shareMethod !== 'string' || !SHARE_METHODS.includes(shareMethod)) {
      throw new ApiError(400, 'VALIDATION_FAILED', '공유 방식은 쪽지 또는 이메일이어야 합니다.');
    }
    const rawTargets = data['targets'];
    if (!Array.isArray(rawTargets) || rawTargets.length === 0) {
      throw new ApiError(422, 'SHARE_TARGET_REQUIRED', '공유 대상자와 권한을 지정해 주세요.');
    }
    const targets: { employeeId: string; canEdit: boolean }[] = [];
    for (const item of rawTargets) {
      if (item === null || typeof item !== 'object') {
        throw new ApiError(422, 'SHARE_TARGET_REQUIRED', '공유 대상자와 권한을 지정해 주세요.');
      }
      const target = item as Record<string, unknown>;
      const employeeId = target['employeeId'];
      const canEdit = target['canEdit'];
      if (employeeId === undefined || employeeId === null || employeeId === '' || typeof canEdit !== 'boolean') {
        throw new ApiError(422, 'SHARE_TARGET_REQUIRED', '공유 대상자와 권한을 지정해 주세요.');
      }
      if (!/^\d+$/.test(String(employeeId))) {
        throw new ApiError(422, 'INVALID_SHARE_PERMISSION', '공유 대상이 올바른 그룹웨어 사용자가 아닙니다.');
      }
      targets.push({ employeeId: String(employeeId), canEdit });
    }

    return transaction(async (db) => {
      const docs = await db.query(
        'SELECT office_document_id AS "officeDocumentId", title, author_id AS "authorId" FROM office_document WHERE office_document_id = CAST(:documentId AS bigint)',
        { documentId },
      );
      if (docs.length === 0) {
        throw new ApiError(404, 'OFFICE_DOCUMENT_NOT_FOUND', '공유할 문서를 찾을 수 없습니다.');
      }
      const doc = docs[0];

      const allowed = await db.query(
        'SELECT 1 AS ok FROM office_document WHERE office_document_id = CAST(:documentId AS bigint) AND author_id = CAST(:userId AS bigint) ' +
          'UNION ALL SELECT 1 AS ok FROM office_document_share WHERE office_document_id = CAST(:documentId AS bigint) AND employee_id = CAST(:userId AS bigint) AND can_edit = true',
        { documentId, userId: user.id },
      );
      if (allowed.length === 0) {
        throw new ApiError(403, 'FORBIDDEN', '이 문서를 공유할 권한이 없습니다.');
      }

      const emails: Record<string, unknown> = {};
      for (const target of targets) {
        const rows = await db.query(
          'SELECT employee_id AS "employeeId", email FROM employee WHERE employee_id = CAST(:employeeId AS bigint) AND employment_status = :status',
          { employeeId: target.employeeId, status: ACTIVE_STATUS },
        );
        if (rows.length === 0) {
          throw new ApiError(422, 'INVALID_SHARE_PERMISSION', '그룹웨어 사용자가 아닌 대상은 공유할 수 없습니다.');
        }
        emails[target.employeeId] = rows[0]['email'];
      }

      for (const target of targets) {
        await db.execute(
          'INSERT INTO office_document_share (office_document_id, employee_id, can_edit, created_at, updated_at) ' +
            'VALUES (CAST(:documentId AS bigint), CAST(:employeeId AS bigint), :canEdit, now(), now()) ' +
            'ON CONFLICT (office_document_id, employee_id) DO UPDATE SET can_edit = :canEdit, updated_at = now()',
          { documentId, employeeId: target.employeeId, canEdit: target.canEdit },
        );
      }

      let notificationStatus = '';
      if (shareMethod === 'NOTE') {
        const sent = await db.query(
          'INSERT INTO messenger_message (sender_id, message_type, content, sent_at, created_at, updated_at) ' +
            "VALUES (CAST(:userId AS bigint), 'NOTE', :content, now(), now(), now()) RETURNING messenger_message_id AS \"messengerMessageId\"",
          { userId: user.id, content: '문서가 공유되었습니다: ' + String(doc['title']) },
        );
        if (sent.length === 0) {
          throw new ApiError(502, 'SHARE_NOTIFICATION_FAILED', '쪽지 발송에 실패했습니다.');
        }
        notificationStatus = '쪽지 발송 완료';
      } else {
        for (const target of targets) {
          const email = emails[target.employeeId];
          if (typeof email !== 'string' || email === '') {
            throw new ApiError(502, 'SHARE_NOTIFICATION_FAILED', '이메일 주소가 없는 대상자가 있어 발송에 실패했습니다.');
          }
        }
        notificationStatus = '이메일 발송 요청 완료';
      }

      const granted = await db.query(
        'SELECT employee_id AS "employeeId", can_edit AS "canEdit" FROM office_document_share WHERE office_document_id = CAST(:documentId AS bigint) ORDER BY employee_id',
        { documentId },
      );
      return { shared: true, grantedPermissions: granted, notificationStatus };
    });
  }
}

