import { useState } from 'react';
import {
  Band,
  Badge,
  DataTable,
  Drawer,
  Field,
  Form,
  LookupSelect,
  Pairs,
  RefName,
  Select,
  call,
} from '../kit';
import type { PageProps, Row } from '../kit';

interface TargetInput {
  employeeId: number | string;
  canEdit: string;
}

const METHOD_NAMES: Record<string, string> = { NOTE: '쪽지', EMAIL: '이메일' };

export default function FnSfr04105Page({ role, notify }: PageProps) {
  const [history, setHistory] = useState<Row[]>([]);
  const [opening, setOpening] = useState(false);
  const [detail, setDetail] = useState<Row | null>(null);
  const [documentId, setDocumentId] = useState<number | string>('');
  const [shareMethod, setShareMethod] = useState('NOTE');
  const [targets, setTargets] = useState<TargetInput[]>([{ employeeId: '', canEdit: 'false' }]);

  const openForm = () => {
    setDocumentId('');
    setShareMethod('NOTE');
    setTargets([{ employeeId: '', canEdit: 'false' }]);
    setOpening(true);
  };

  const changeTarget = (index: number, patch: Partial<TargetInput>) => {
    setTargets(targets.map((t, i) => (i === index ? { ...t, ...patch } : t)));
  };

  const submit = async () => {
    if (documentId === '') {
      throw new Error('공유할 문서를 선택해 주세요.');
    }
    if (targets.length === 0 || targets.some((t) => t.employeeId === '')) {
      throw new Error('공유 대상자와 권한을 모두 지정해 주세요.');
    }
    const body: Row = {
      shareMethod,
      targets: targets.map((t) => ({ employeeId: t.employeeId, canEdit: t.canEdit === 'true' })),
    };
    const result = await call('POST', '/office-documents/' + documentId + '/share', role, body);
    notify('문서를 공유했습니다.');
    setHistory([{ ...result, documentId, shareMethod, sharedCount: targets.length }, ...history]);
    setOpening(false);
  };

  return (
    <div className="doc">
      <section className="box">
        <h2>웹 오피스 문서 공유</h2>
        <Band total={history.length}>
          <button onClick={openForm}>문서 공유</button>
        </Band>
        <DataTable
          columns={[
            {
              key: 'documentId',
              label: '문서',
              render: (row) => <RefName table="office_document" role={role} value={row['documentId']} />,
            },
            {
              key: 'shareMethod',
              label: '공유 방식',
              render: (row) => METHOD_NAMES[String(row['shareMethod'])] ?? String(row['shareMethod']),
            },
            { key: 'sharedCount', label: '대상자 수' },
            {
              key: 'shared',
              label: '공유 완료 여부',
              render: (row) => <Badge value={row['shared'] ? '완료' : '실패'} />,
            },
            { key: 'notificationStatus', label: '공유 안내 발송 결과' },
          ]}
          rows={history}
          onRowClick={(row) => setDetail(row)}
          empty="아직 공유한 문서가 없습니다. 문서 공유 버튼을 눌러 시작해 주세요."
        />
      </section>
      {opening && (
        <Drawer title="문서 공유" onClose={() => setOpening(false)}>
          <Form
            onSubmit={submit}
            submit="공유"
            note="공유하면 대상자에게 안내가 발송되고 대상자의 공유 문서함에 문서가 표시됩니다."
          >
            <Field label="공유할 문서" required wide>
              <LookupSelect
                table="office_document"
                role={role}
                value={documentId}
                onChange={setDocumentId}
                placeholder="문서 선택"
              />
            </Field>
            <Field label="공유 방식 (NOTE 쪽지 또는 EMAIL 이메일)" required wide>
              <Select
                value={shareMethod}
                onChange={setShareMethod}
                options={[
                  ['NOTE', '쪽지'],
                  ['EMAIL', '이메일'],
                ]}
              />
            </Field>
            {targets.map((target, index) => (
              <Field key={index} label={'공유 대상자 ' + (index + 1)} required wide hint="수정 권한에는 열람 권한이 함께 부여됩니다.">
                <LookupSelect
                  table="employee"
                  role={role}
                  value={target.employeeId}
                  onChange={(v) => changeTarget(index, { employeeId: v })}
                  placeholder="대상자 선택"
                />
                <Select
                  value={target.canEdit}
                  onChange={(v) => changeTarget(index, { canEdit: v })}
                  options={[
                    ['false', '열람만'],
                    ['true', '열람 및 수정'],
                  ]}
                />
                {targets.length > 1 && (
                  <button type="button" className="ghost" onClick={() => setTargets(targets.filter((_, i) => i !== index))}>
                    삭제
                  </button>
                )}
              </Field>
            ))}
            <button
              type="button"
              className="ghost"
              onClick={() => setTargets([...targets, { employeeId: '', canEdit: 'false' }])}
            >
              대상자 추가
            </button>
          </Form>
        </Drawer>
      )}
      {detail && (
        <Drawer title="공유 결과" onClose={() => setDetail(null)}>
          <Pairs
            items={[
              ['문서', <RefName table="office_document" role={role} value={detail['documentId']} />],
              ['공유 방식', METHOD_NAMES[String(detail['shareMethod'])] ?? String(detail['shareMethod'])],
              ['공유 완료 여부', <Badge value={detail['shared'] ? '완료' : '실패'} />],
              ['공유 안내 발송 결과', String(detail['notificationStatus'] ?? '')],
              [
                '대상자별 부여 권한',
                <div>
                  {((detail['grantedPermissions'] as Row[] | undefined) ?? []).map((p, i) => (
                    <p key={i}>
                      <RefName table="employee" role={role} value={p['employeeId']} />
                      {p['canEdit'] ? ' — 열람 및 수정' : ' — 열람만'}
                    </p>
                  ))}
                </div>,
              ],
            ]}
          />
        </Drawer>
      )}
    </div>
  );
}
